/* ── Small helpers ─────────────────────────────────────────────────────────── */

export const esc = (s: unknown) =>
  String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');

const HEX = /^#[0-9a-f]{6}$/i;
const hex = (v: string | null | undefined, fallback: string) => (v && HEX.test(v) ? v : fallback);

function lum(h: string) {
  const n = parseInt(h.slice(1), 16);
  const c = [16, 8, 0].map(s => {
    const v = ((n >> s) & 255) / 255;
    return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4);
  });
  return 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2];
}
export const inkOn = (bg: string) => (lum(bg) > 0.45 ? '#0B1220' : '#FFFFFF');
export function mix(a: string, b: string, t: number) {
  const x = parseInt(a.slice(1), 16), y = parseInt(b.slice(1), 16);
  const ch = (v: number, s: number) => (v >> s) & 255;
  return '#' + [16, 8, 0].map(s => Math.round(ch(x, s) * (1 - t) + ch(y, s) * t).toString(16).padStart(2, '0')).join('');
}

const SAFE_FONTS = ['Outfit', 'Inter', 'Montserrat', 'Open Sans', 'Poppins', 'Lato', 'Roboto', 'Raleway', 'Instrument Sans'];
const stack = (f: string) => `'${SAFE_FONTS.includes(f) ? f : 'Inter'}',Arial,Helvetica,sans-serif`;

const DAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const MONTHS_LONG = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];

/** 'YYYY-MM-DD' (or an ISO time) as a calendar date, never shifted by time zones. */
function ymd(s?: string | null): { y: number; m: number; d: number; dow: number } | null {
  const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(s || '');
  if (!m) return null;
  const dt = new Date(Date.UTC(+m[1], +m[2] - 1, +m[3]));
  return { y: +m[1], m: +m[2] - 1, d: +m[3], dow: dt.getUTCDay() };
}
export const fmtDay = (s?: string | null) => { const v = ymd(s); return v ? `${DAYS[v.dow]} ${v.d} ${MONTHS[v.m]}` : ''; };
export const fmtLong = (s?: string | null) => { const v = ymd(s); return v ? `${v.d} ${MONTHS_LONG[v.m]} ${v.y}` : ''; };
const dayDiff = (from: string, to: string) => {
  const a = ymd(from), b = ymd(to);
  if (!a || !b) return 0;
  return Math.round((Date.UTC(b.y, b.m, b.d) - Date.UTC(a.y, a.m, a.d)) / 86400000);
};

/** Today in the club's time zone as YYYY-MM-DD. */
export function todayIn(tz = 'Australia/Sydney') {
  try {
    return new Intl.DateTimeFormat('en-CA', { timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
  } catch {
    return new Date().toISOString().slice(0, 10);
  }
}

const money = (n?: number | null) =>
  n == null ? '' : `$${Number(n).toLocaleString('en-AU', { minimumFractionDigits: Number(n) % 1 ? 2 : 0, maximumFractionDigits: 2 })}`;

/** Personal details in text: {first_name}, {last_name}, {club_name}. */
export function fillTokens(s: string, reader: Reader, brand: Brand) {
  return String(s || '')
    .replace(/\{first_name\}/g, reader.first_name || 'there')
    .replace(/\{last_name\}/g, reader.last_name || '')
    .replace(/\{club_name\}/g, brand.clubName || '');
}

const okUrl = (u?: string | null) => !!u && /^(https?:\/\/|mailto:|tel:)/i.test(u.trim());

/* ── Rendering context ─────────────────────────────────────────────────────── */

interface Ctx {
  o: RenderOptions;
  brand: Brand;
  primary: string;
  dark: string;
  accent: string;
  hf: string;
  bf: string;
  btnR: number;
  cardR: number;
  today: string;
  block: Block;
}

const link = (c: Ctx, url?: string | null) => {
  if (!okUrl(url)) return '#';
  const u = url!.trim();
  if (c.o.edit || !c.o.wrapLink || !/^https?:/i.test(u)) return u;
  return c.o.wrapLink(u, c.block.id);
};

/** Markdown-lite: **bold**, *italic*, [text](url), "- " bullets, blank line = new paragraph. */
function md(c: Ctx, raw: string, color = '#334155', size = 15, align = 'left') {
  const text = fillTokens(raw, c.o.reader, c.brand);
  const inline = (s: string) =>
    esc(s)
      .replace(/\[([^\]]+)\]\(([^)\s]+)\)/g, (_m, t, u) => {
        const url = u.replace(/&amp;/g, '&');
        return `<a href="${esc(link(c, url))}" style="color:${c.primary};font-weight:600;text-decoration:underline">${t}</a>`;
      })
      .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
      .replace(/(^|[^*])\*([^*\n]+)\*/g, '$1<em>$2</em>');
  const pars = text.split(/\n\s*\n/).filter(p => p.trim() !== '');
  return pars.map((par, i) => {
    const mb = i === pars.length - 1 ? 0 : 14;
    const lines = par.split('\n');
    if (lines.every(l => /^\s*[-•]\s+/.test(l))) {
      return `<ul style="margin:0 0 ${mb}px;padding:0 0 0 20px;font-family:${c.bf};font-size:${size}px;line-height:1.6;color:${color};text-align:left">`
        + lines.map(l => `<li style="margin:0 0 4px">${inline(l.replace(/^\s*[-•]\s+/, ''))}</li>`).join('') + '</ul>';
    }
    return `<p style="margin:0 0 ${mb}px;font-family:${c.bf};font-size:${size}px;line-height:1.6;color:${color};text-align:${align}">${lines.map(inline).join('<br>')}</p>`;
  }).join('');
}

function button(c: Ctx, text: string, url: string | null | undefined, opts: { style?: 'solid' | 'outline'; align?: string; full?: boolean; color?: string; small?: boolean } = {}) {
  if (!text) return '';
  const col = opts.color || c.primary;
  const outline = (opts.style || c.brand.buttons) === 'outline';
  const ink = outline ? col : inkOn(col);
  const pad = opts.small ? '9px 16px' : '13px 22px';
  const fs = opts.small ? 13 : 15;
  const href = esc(link(c, url));
  const cell = outline
    ? `border:2px solid ${col};border-radius:${c.btnR}px;`
    : `background:${col};border-radius:${c.btnR}px;`;
  return `<table role="presentation" cellpadding="0" cellspacing="0" border="0"${opts.align === 'center' ? ' align="center"' : ''} style="border-collapse:separate;${opts.align === 'center' ? 'margin:0 auto;' : ''}${opts.full ? 'width:100%;' : ''}"><tr>`
    + `<td align="center" bgcolor="${outline ? '#FFFFFF' : col}" style="${cell}">`
    + `<a href="${href}" target="_blank" style="display:block;padding:${pad};font-family:${c.bf};font-size:${fs}px;font-weight:700;line-height:1.2;color:${ink};text-decoration:none;white-space:nowrap">${esc(text)}</a>`
    + '</td></tr></table>';
}

const title = (c: Ctx, t?: string, size = 19) =>
  t ? `<div style="margin:0 0 12px;font-family:${c.hf};font-size:${size}px;font-weight:800;line-height:1.25;color:#0B1220">${esc(fillTokens(t, c.o.reader, c.brand))}</div>` : '';

const placeholder = (msg: string) =>
  `<div style="border:2px dashed #CBD5E1;border-radius:12px;padding:18px;text-align:center;font-family:Arial,sans-serif;font-size:13px;line-height:1.5;color:#64748B">${esc(msg)}</div>`;

const sourcePill = (c: Ctx, s: FeedNews['source']) => {
  const map = { club: { bg: mix(c.primary, '#FFFFFF', 0.86), fg: mix(c.primary, '#000000', 0.25), t: 'CLUB' }, state: { bg: '#EDE7FF', fg: '#5B2BD6', t: 'STATE' }, national: { bg: '#FFEDD5', fg: '#C2410C', t: 'NATIONAL' } } as const;
  const m = map[s] || map.club;
  return `<span style="display:inline-block;padding:2px 7px;border-radius:99px;background:${m.bg};color:${m.fg};font-family:Arial,sans-serif;font-size:10px;font-weight:700;letter-spacing:0.05em">${m.t}</span>`;
};

const bgCell = (url: string | null | undefined, h: number, r: number) =>
  `<td height="${h}" bgcolor="#E2E8F0" style="height:${h}px;border-radius:${r}px;background-color:#E2E8F0;${url ? `background-image:url('${esc(url)}');background-size:cover;background-position:center;` : ''}line-height:${h}px;font-size:0">&nbsp;</td>`;

const cols = (cells: string[], gap = 14) => {
  const w = Math.floor(100 / cells.length);
  return '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr>'
    + cells.map((cell, i) => `<td class="es-col" valign="top" width="${w}%" style="width:${w}%;padding:0 ${i < cells.length - 1 ? gap / 2 : 0}px 0 ${i > 0 ? gap / 2 : 0}px">${cell}</td>`).join('')
    + '</tr></table>';
};
const chunk = <T,>(a: T[], n: number) => Array.from({ length: Math.ceil(a.length / n) }, (_v, i) => a.slice(i * n, i * n + n));

/* ── Blocks ────────────────────────────────────────────────────────────────── */

type Out = { html: string; bleed?: boolean } | null;

const R: { [K in Block['type']]: (c: Ctx, p: BlockProps[K]) => Out } = {
  header(c, p) {
    const bg = p.tone === 'primary' ? c.primary : p.tone === 'light' ? '#FFFFFF' : c.dark;
    const ink = inkOn(bg);
    const logo = p.tone === 'light' ? (c.brand.logo || c.brand.logoDark) : (c.brand.logoDark || c.brand.logo);
    const showLogo = p.show !== 'name' && !!logo;
    const showName = p.show !== 'logo' || !logo;
    const left = (showLogo ? `<img src="${esc(logo)}" alt="${esc(c.brand.clubName)}" height="40" style="display:inline-block;height:40px;width:auto;max-width:160px;border:0;vertical-align:middle;margin-right:${showName ? 12 : 0}px">` : '')
      + (showName ? `<span style="font-family:${c.hf};font-size:15px;font-weight:800;letter-spacing:0.04em;color:${ink};vertical-align:middle;text-transform:uppercase">${esc(c.brand.clubName)}</span>` : '');
    return {
      bleed: true,
      html: `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="${bg}" style="background:${bg};${p.tone === 'light' ? 'border-bottom:1px solid #E5E9F0;' : ''}"><tr>`
        + `<td class="es-px" style="padding:18px 28px">${left}</td>`
        + (p.note ? `<td class="es-px" align="right" style="padding:18px 28px;font-family:${c.bf};font-size:12px;color:${ink};opacity:0.8;white-space:nowrap">${esc(fillTokens(p.note, c.o.reader, c.brand))}</td>` : '')
        + '</tr></table>',
    };
  },

  hero(c, p) {
    const h = p.height === 'sm' ? 170 : p.height === 'lg' ? 300 : 230;
    const img = okUrl(p.image) ? p.image! : '';
    const bg = img
      ? `background-color:${c.dark};background-image:linear-gradient(180deg,rgba(0,0,0,0.05) 25%,rgba(0,0,0,0.65)),url('${esc(img)}');background-size:cover;background-position:center;`
      : `background-color:${c.dark};background-image:linear-gradient(135deg,${c.dark},${c.primary});`;
    const label = p.label ? `<span style="display:inline-block;margin:0 0 10px;padding:4px 10px;border-radius:99px;background:${c.accent};color:${inkOn(c.accent)};font-family:Arial,sans-serif;font-size:11px;font-weight:700;letter-spacing:0.08em;text-transform:uppercase">${esc(p.label)}</span><br>` : '';
    return {
      bleed: true,
      html: `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr>`
        + `<td class="es-px" height="${h}" valign="bottom" bgcolor="${c.dark}" style="height:${h}px;${bg}padding:24px 28px">`
        + label
        + (p.title ? `<div style="font-family:${c.hf};font-size:30px;font-weight:800;line-height:1.15;color:#FFFFFF;margin:0">${esc(fillTokens(p.title, c.o.reader, c.brand))}</div>` : '')
        + (p.text ? `<div style="font-family:${c.bf};font-size:15px;line-height:1.5;color:rgba(255,255,255,0.9);margin:8px 0 0">${esc(fillTokens(p.text, c.o.reader, c.brand))}</div>` : '')
        + (p.buttonText ? `<div style="margin:16px 0 0">${button(c, p.buttonText, p.url, { color: c.accent, style: 'solid' })}</div>` : '')
        + '</td></tr></table>',
    };
  },

  heading(c, p) {
    const size = p.size === 'lg' ? 26 : p.size === 'sm' ? 16 : 20;
    return { html: `<div style="font-family:${c.hf};font-size:${size}px;font-weight:800;line-height:1.25;color:#0B1220;text-align:${p.align}">${esc(fillTokens(p.text, c.o.reader, c.brand))}</div>` };
  },

  text(c, p) {
    if (!String(p.text || '').trim()) return c.o.edit ? { html: placeholder('Type your text in the panel on the right') } : null;
    return { html: md(c, p.text || '', '#334155', 15, p.align) };
  },

  button(c, p) {
    return { html: button(c, p.text, p.url, { style: p.style, align: p.align, full: p.full }) };
  },

  image(c, p) {
    if (!okUrl(p.src)) return c.o.edit ? { html: placeholder('Add an image in the panel on the right') } : null;
    const r = p.inset ? c.cardR : 0;
    const img = `<img src="${esc(p.src)}" alt="${esc(p.alt || '')}" width="${p.inset ? 544 : 600}" style="display:block;width:100%;max-width:${p.inset ? 544 : 600}px;height:auto;border:0;border-radius:${r}px">`;
    const body = (okUrl(p.url) ? `<a href="${esc(link(c, p.url))}" target="_blank" style="text-decoration:none">${img}</a>` : img)
      + (p.caption ? `<div style="font-family:${c.bf};font-size:12px;line-height:1.5;color:#64748B;margin:8px ${p.inset ? 0 : 28}px 0">${esc(p.caption)}</div>` : '');
    return { html: body, bleed: !p.inset };
  },

  divider() {
    return { html: '<div style="height:1px;line-height:1px;font-size:0;background:#E5E9F0">&nbsp;</div>' };
  },

  spacer(_c, p) {
    const h = p.size === 'sm' ? 8 : p.size === 'lg' ? 40 : 22;
    return { html: `<div style="height:${h}px;line-height:${h}px;font-size:0">&nbsp;</div>` };
  },

  columns(c, p) {
    const items = (p.items || []).slice(0, p.cols);
    const cards = items.map(it =>
      (okUrl(it.image) ? `<img src="${esc(it.image)}" alt="" width="260" style="display:block;width:100%;height:auto;border:0;border-radius:${c.cardR}px;margin:0 0 10px">` : '')
      + (it.title ? `<div style="font-family:${c.hf};font-size:16px;font-weight:800;line-height:1.3;color:#0B1220;margin:0 0 6px">${esc(fillTokens(it.title, c.o.reader, c.brand))}</div>` : '')
      + (it.text ? `<div style="font-family:${c.bf};font-size:14px;line-height:1.55;color:#475569;margin:0 0 10px">${esc(fillTokens(it.text, c.o.reader, c.brand))}</div>` : '')
      + (it.buttonText ? button(c, it.buttonText, it.url, { small: true }) : ''));
    if (!cards.length) return c.o.edit ? { html: placeholder('Add some cards in the panel on the right') } : null;
    return { html: cols(cards, 18) };
  },

  quote(c, p) {
    return {
      html: `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr><td style="border-left:4px solid ${c.accent};padding:4px 0 4px 18px">`
        + `<div style="font-family:${c.hf};font-size:19px;font-style:italic;font-weight:600;line-height:1.45;color:#0B1220">“${esc(fillTokens(p.text, c.o.reader, c.brand))}”</div>`
        + (p.by ? `<div style="font-family:${c.bf};font-size:13px;color:#64748B;margin-top:8px">${esc(p.by)}</div>` : '')
        + '</td></tr></table>',
    };
  },

  social(c, p) {
    const names = { website: 'Website', facebook: 'Facebook', instagram: 'Instagram', youtube: 'YouTube', x: 'X' } as const;
    const links = (p.links || []).filter(l => okUrl(l.url));
    if (!links.length) return c.o.edit ? { html: placeholder('Add your website and social links in the panel on the right') } : null;
    return {
      html: (p.title ? `<div style="font-family:${c.hf};font-size:15px;font-weight:800;color:#0B1220;text-align:center;margin:0 0 10px">${esc(p.title)}</div>` : '')
        + '<div style="text-align:center">' + links.map(l => `<a href="${esc(link(c, l.url))}" target="_blank" style="display:inline-block;margin:0 4px 8px;padding:8px 14px;border-radius:99px;border:1px solid #D9E0EA;font-family:${c.bf};font-size:13px;font-weight:700;color:#0B1220;text-decoration:none">${names[l.kind] || 'Link'}</a>`).join('') + '</div>',
    };
  },

  logos(c, p) {
    const items = (p.items || []).filter(i => okUrl(i.src));
    if (!items.length) return c.o.edit ? { html: placeholder('Add sponsor logos in the panel on the right') } : null;
    const imgs = items.map(i => {
      const img = `<img src="${esc(i.src)}" alt="${esc(i.alt || '')}" height="44" style="display:inline-block;height:44px;width:auto;max-width:140px;border:0;margin:6px 12px;vertical-align:middle">`;
      return okUrl(i.url) ? `<a href="${esc(link(c, i.url))}" target="_blank">${img}</a>` : img;
    }).join('');
    return { html: (p.title ? `<div style="font-family:${c.bf};font-size:12px;font-weight:700;letter-spacing:0.06em;text-transform:uppercase;color:#64748B;text-align:center;margin:0 0 8px">${esc(p.title)}</div>` : '') + `<div style="text-align:center">${imgs}</div>` };
  },

  /* ── Club content ─────────────────────────────────────────────────────── */

  news(c, p) {
    const f = c.o.feed;
    let items = f.news.filter(n => p.sources.includes(n.source));
    const since = f.lastSentAt && p.sinceLastSend ? f.lastSentAt : null;
    let fresh = since ? items.filter(n => (n.published_at || '') > since) : items;
    if (!fresh.length && since && p.whenEmpty === 'older') fresh = items;
    items = fresh;
    const order = { club: 0, state: 1, national: 2 } as const;
    items = [...items].sort((a, b) => (p.clubFirst ? order[a.source] - order[b.source] : 0) || (b.published_at || '').localeCompare(a.published_at || ''));
    items = items.slice(0, Math.max(1, Math.min(6, p.count || 3)));
    if (!items.length) return c.o.edit ? { html: title(c, p.title) + placeholder('No news to show right now. This block is left out until there is some.') } : null;

    const meta = (n: FeedNews) => (p.showSource ? sourcePill(c, n.source) + '&nbsp; ' : '')
      + (n.published_at ? `<span style="font-family:${c.bf};font-size:11.5px;color:#94A3B8">${esc(fmtDay(n.published_at))}</span>` : '');
    const head = (n: FeedNews, size: number) => `<a href="${esc(link(c, n.url))}" target="_blank" style="font-family:${c.hf};font-size:${size}px;font-weight:800;line-height:1.3;color:#0B1220;text-decoration:none">${esc(n.title)}</a>`;
    const sum = (n: FeedNews) => p.showSummary && n.excerpt ? `<div style="font-family:${c.bf};font-size:13.5px;line-height:1.5;color:#475569;margin:6px 0 0">${esc(n.excerpt.length > 150 ? n.excerpt.slice(0, 147).trimEnd() + '…' : n.excerpt)}</div>` : '';
    const small = (n: FeedNews) => '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:0 0 14px"><tr>'
      + (p.showImages && n.image ? `<td width="88" valign="top" style="width:88px;padding-right:12px"><table role="presentation" width="88" cellpadding="0" cellspacing="0" border="0"><tr>${bgCell(n.image, 70, Math.min(c.cardR, 10))}</tr></table></td>` : '')
      + `<td valign="top"><div style="margin:0 0 4px">${meta(n)}</div>${head(n, 15)}${p.layout === 'list' ? sum(n) : ''}</td></tr></table>`;
    const card = (n: FeedNews, big = false) =>
      (p.showImages && n.image ? `<a href="${esc(link(c, n.url))}" target="_blank" style="text-decoration:none"><img src="${esc(n.image)}" alt="" width="${big ? 300 : 260}" style="display:block;width:100%;height:auto;border:0;border-radius:${c.cardR}px;margin:0 0 10px"></a>` : '')
      + `<div style="margin:0 0 4px">${meta(n)}</div>${head(n, big ? 18 : 16)}${sum(n)}`;

    let body = '';
    if (p.layout === 'list') body = items.map(small).join('');
    else if (p.layout === 'cards') body = chunk(items, 2).map(r => cols(r.map(n => card(n)).concat(r.length < 2 ? [''] : []), 18)).join('<div style="height:16px;line-height:16px;font-size:0">&nbsp;</div>');
    else body = items.length === 1 ? card(items[0], true) : cols([card(items[0], true), items.slice(1).map(small).join('')], 20);

    return { html: title(c, p.title) + body + (p.buttonText ? `<div style="margin-top:6px">${button(c, p.buttonText, `${f.club.siteUrl}/news`, { style: 'outline', small: true })}</div>` : '') };
  },

  events(c, p) {
    const f = c.o.feed;
    const end = addDays(c.today, p.daysAhead || 30);
    let evs = f.events.filter(e => e.kind !== 'meeting' && e.event_date >= c.today && e.event_date <= end);
    if (p.myClasses) evs = evs.filter(e => mine(e, c.o.reader));
    evs = evs.slice(0, Math.max(1, Math.min(6, p.count || 3)));
    if (!evs.length) return c.o.edit ? { html: title(c, p.title) + placeholder('No events coming up in this window. This block is left out until there are some.') } : null;
    const body = evs.map(e => eventCard(c, e, p)).join('<div style="height:12px;line-height:12px;font-size:0">&nbsp;</div>');
    return { html: title(c, p.title) + body + (p.buttonText ? `<div style="margin-top:14px">${button(c, p.buttonText, `${f.club.siteUrl}/race-calendar`, { style: 'outline', small: true })}</div>` : '') };
  },

  results(c, p) {
    const f = c.o.feed;
    const rs = f.results.slice(0, Math.max(1, Math.min(3, p.count || 1)));
    if (!rs.length) return c.o.edit ? { html: title(c, p.title) + placeholder('No results yet. This block is left out until some are published.') } : null;
    const me = `${c.o.reader.first_name} ${c.o.reader.last_name || ''}`.trim().toLowerCase();
    const medal = ['#D4A017', '#94A3B8', '#B87333'];
    const body = rs.map(r => {
      const top = r.standings.slice(0, Math.max(1, Math.min(10, p.top || 3)));
      const mineIdx = p.highlightReader && me.length > 2 ? r.standings.findIndex(s => s.name.trim().toLowerCase() === me) : -1;
      const row = (s: typeof top[number], you: boolean) => `<tr><td style="padding:8px 14px;border-top:1px solid #EEF2F6;${you ? 'background:#FFF7ED;' : ''}">`
        + `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr>`
        + `<td width="28" style="width:28px"><span style="display:inline-block;width:22px;height:22px;line-height:22px;border-radius:99px;text-align:center;background:${medal[s.pos - 1] || '#E2E8F0'};color:${s.pos <= 3 ? '#FFFFFF' : '#334155'};font-family:Arial,sans-serif;font-size:11px;font-weight:700">${s.pos}</span></td>`
        + `<td style="font-family:${c.bf};font-size:14px;color:#0B1220;font-weight:${you ? 700 : 500}">${esc(you ? `You, ${s.name}` : s.name)}${s.sail ? ` <span style="color:#94A3B8;font-weight:400">#${esc(s.sail)}</span>` : ''}</td>`
        + `<td align="right" style="font-family:${c.bf};font-size:12.5px;color:#64748B;white-space:nowrap">${s.points != null ? `${s.points} pts` : ''}</td>`
        + '</tr></table></td></tr>';
      const rows = top.map(s => row(s, s.pos - 1 === mineIdx)).join('')
        + (mineIdx >= top.length ? row(r.standings[mineIdx], true) : '');
      return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="border:1px solid #E2E8F0;border-radius:${c.cardR}px;border-collapse:separate;overflow:hidden">`
        + `<tr><td style="padding:11px 14px;background:#F8FAFC;border-radius:${c.cardR}px ${c.cardR}px 0 0"><a href="${esc(link(c, r.url))}" target="_blank" style="font-family:${c.hf};font-size:14.5px;font-weight:800;color:#0B1220;text-decoration:none">${esc(r.title)}</a>`
        + `<div style="font-family:${c.bf};font-size:12px;color:#64748B;margin-top:2px">${esc([fmtDay(r.date), r.race_class, r.boats ? `${r.boats} boats` : ''].filter(Boolean).join(' · '))}</div></td></tr>`
        + rows + '</table>'
        + (p.buttonText ? `<div style="margin-top:12px">${button(c, p.buttonText, r.url, { small: true })}</div>` : '');
    }).join('<div style="height:16px;line-height:16px;font-size:0">&nbsp;</div>');
    return { html: title(c, p.title) + body };
  },

  classifieds(c, p) {
    const f = c.o.feed;
    let items = p.scope === 'club' ? f.classifieds.filter(i => i.mine) : f.classifieds;
    if (p.category) items = items.filter(i => (i.category || '').toLowerCase() === p.category!.toLowerCase());
    items = items.slice(0, Math.max(1, Math.min(9, p.count || 3)));
    if (!items.length) return c.o.edit ? { html: title(c, p.title) + placeholder('No listings to show right now.') } : null;
    const card = (i: typeof items[number]) => `<a href="${esc(link(c, i.url))}" target="_blank" style="text-decoration:none;color:#0B1220">`
      + `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr>${bgCell(i.image, 110, Math.min(c.cardR, 10))}</tr></table>`
      + (p.showPrice && i.price != null ? `<div style="font-family:${c.bf};font-size:14px;font-weight:800;color:${c.primary};margin:8px 0 2px">${esc(money(i.price))}</div>` : '<div style="height:8px"></div>')
      + `<div style="font-family:${c.bf};font-size:13px;line-height:1.35;color:#0B1220">${esc(i.title)}</div>`
      + (i.location ? `<div style="font-family:${c.bf};font-size:11.5px;color:#94A3B8;margin-top:2px">${esc(i.location)}</div>` : '')
      + '</a>';
    const rows = chunk(items, 3).map(r => cols([...r.map(card), ...Array(3 - r.length).fill('')], 12)).join('<div style="height:14px;line-height:14px;font-size:0">&nbsp;</div>');
    return { html: title(c, p.title) + rows + (p.buttonText ? `<div style="margin-top:14px">${button(c, p.buttonText, `${f.club.siteUrl}/classifieds`, { style: 'outline', small: true })}</div>` : '') };
  },

  videos(c, p) {
    const f = c.o.feed;
    const items = (p.source === 'club' ? f.videos.filter(v => v.mine) : f.videos).slice(0, Math.max(1, Math.min(4, p.count || 3)));
    if (!items.length) return c.o.edit ? { html: title(c, p.title) + placeholder('No videos to show right now.') } : null;
    const thumb = (v: typeof items[number], big: boolean) => `<a href="${esc(link(c, v.url))}" target="_blank" style="text-decoration:none;color:#0B1220">`
      + (v.thumb ? `<img src="${esc(v.thumb)}" alt="" width="${big ? 544 : 262}" style="display:block;width:100%;height:auto;border:0;border-radius:${Math.min(c.cardR, 10)}px">` : `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr>${bgCell(null, big ? 240 : 120, 10)}</tr></table>`)
      + `<div style="font-family:${c.bf};font-size:${big ? 15 : 13}px;font-weight:700;line-height:1.35;margin:8px 0 0">&#9654;&nbsp; ${esc(v.title)}</div>`
      + (v.duration ? `<div style="font-family:${c.bf};font-size:11.5px;color:#94A3B8;margin-top:2px">${esc(v.duration)}</div>` : '')
      + '</a>';
    const [first, ...rest] = items;
    const body = items.length === 2
      ? cols(items.map(v => thumb(v, false)), 14)
      : thumb(first, true) + (rest.length ? '<div style="height:16px;line-height:16px;font-size:0">&nbsp;</div>' + cols(rest.map(v => thumb(v, false)), 12) : '');
    return { html: title(c, p.title) + body + (p.buttonText ? `<div style="margin-top:14px">${button(c, p.buttonText, `${f.club.appUrl}/alfie-tv`, { style: 'outline', small: true })}</div>` : '') };
  },

  membership(c, p) {
    const r = c.o.reader;
    const today = c.today;
    let kicker = (p.title || 'Your membership').toUpperCase();
    let head = '';
    let sub = '';
    let cta = '';
    let url: string | null | undefined = r.renewUrl;
    if (!r.is_member) {
      kicker = 'JOIN THE CLUB';
      head = `Sail with ${c.brand.clubName}`;
      sub = 'Race days, club events and a great crew. Join online in a few minutes.';
      cta = p.joinText || 'Join the club';
      url = `${c.o.feed.club.appUrl}/register`;
    } else if (r.renewal_date && r.renewal_date < today) {
      head = 'Your membership has lapsed';
      sub = `It was due on ${fmtLong(r.renewal_date)}. Renew to keep racing.`;
      cta = p.renewText || 'Renew now';
    } else if (r.renewal_date && dayDiff(today, r.renewal_date) <= 45) {
      const n = dayDiff(today, r.renewal_date);
      head = n <= 0 ? 'Your membership renews today' : `Renews in ${n} day${n === 1 ? '' : 's'}`;
      sub = `${r.membership_level ? `${r.membership_level} · ` : ''}due ${fmtLong(r.renewal_date)}`;
      cta = p.renewText || 'Renew now';
    } else if (r.is_financial === false) {
      head = 'Your membership needs renewing';
      sub = 'Renew to keep racing with the club.';
      cta = p.renewText || 'Renew now';
    } else {
      if (!p.showWhenCurrent) return c.o.edit ? { html: placeholder('This reader is all paid up, so this block is left out for them.') } : null;
      head = 'You’re all set';
      sub = r.renewal_date ? `${r.membership_level ? `${r.membership_level} · ` : ''}paid up until ${fmtLong(r.renewal_date)}` : 'Thanks for being a member.';
      cta = 'View my membership';
    }
    return {
      html: `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="border-collapse:separate"><tr>`
        + `<td bgcolor="${c.dark}" style="padding:20px 22px;border-radius:${c.cardR}px;background-color:${c.dark};background-image:linear-gradient(135deg,${c.dark},${c.primary})">`
        + `<div style="font-family:Arial,sans-serif;font-size:11px;font-weight:700;letter-spacing:0.08em;color:rgba(255,255,255,0.75)">${esc(kicker)}</div>`
        + `<div style="font-family:${c.hf};font-size:21px;font-weight:800;line-height:1.25;color:#FFFFFF;margin:6px 0 4px">${esc(head)}</div>`
        + `<div style="font-family:${c.bf};font-size:13.5px;line-height:1.5;color:rgba(255,255,255,0.85);margin:0 0 14px">${esc(sub)}</div>`
        + button(c, cta, url || `${c.o.feed.club.appUrl}/login`, { color: c.accent, style: 'solid', small: true })
        + '</td></tr></table>',
    };
  },

  calendar(c, p) {
    const f = c.o.feed;
    const end = addDays(c.today, (p.weeks || 4) * 7);
    let evs = f.events.filter(e => e.event_date >= c.today && e.event_date <= end);
    if (p.myClasses) evs = evs.filter(e => e.kind === 'meeting' || mine(e, c.o.reader));
    evs = evs.slice(0, 12);
    if (!evs.length) return c.o.edit ? { html: title(c, p.title) + placeholder('Nothing on the race calendar in this window.') } : null;
    const rows = evs.map(e => `<tr><td width="70" valign="top" style="width:70px;padding:9px 0;border-top:1px solid #EEF2F6;font-family:${c.bf};font-size:12.5px;font-weight:700;color:${c.primary};white-space:nowrap">${esc(fmtDay(e.event_date).replace(/ \w+$/, ''))}<div style="font-weight:400;color:#94A3B8;font-size:11px">${esc(fmtDay(e.event_date).split(' ').pop())}</div></td>`
      + `<td valign="top" style="padding:9px 0 9px 8px;border-top:1px solid #EEF2F6;font-family:${c.bf};font-size:13.5px;line-height:1.4;color:#0B1220"><a href="${esc(link(c, e.url))}" target="_blank" style="color:#0B1220;text-decoration:none;font-weight:600">${esc(e.title)}</a>`
      + `<div style="font-size:12px;color:#64748B">${esc([e.race_class, p.showVenue ? e.venue : null, e.start_time ? `first start ${e.start_time}` : null].filter(Boolean).join(' · '))}</div></td></tr>`).join('');
    return { html: title(c, p.title) + `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">${rows}</table>` + (p.buttonText ? `<div style="margin-top:14px">${button(c, p.buttonText, `${f.club.siteUrl}/race-calendar`, { style: 'outline', small: true })}</div>` : '') };
  },

  countdown(c, p) {
    const e = c.o.feed.events.find(x => x.event_key === p.eventKey) || (!p.eventKey ? c.o.feed.events.find(x => x.kind !== 'meeting' && x.event_date >= c.today) : undefined);
    if (!e) return c.o.edit ? { html: placeholder('Pick an event for the countdown in the panel on the right.') } : null;
    const days = Math.max(0, dayDiff(c.today, e.event_date));
    const box = (n: string | number, l: string) => `<td width="33%" align="center" style="width:33%;padding:0 5px"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="border-collapse:separate"><tr><td align="center" bgcolor="${c.dark}" style="background:${c.dark};border-radius:${Math.min(c.cardR, 12)}px;padding:12px 4px"><div style="font-family:${c.hf};font-size:26px;font-weight:800;color:#FFFFFF;line-height:1.1">${n}</div><div style="font-family:Arial,sans-serif;font-size:10px;font-weight:700;letter-spacing:0.08em;color:rgba(255,255,255,0.75)">${l}</div></td></tr></table></td>`;
    const range = e.end_date && e.end_date > e.event_date ? `${fmtDay(e.event_date)} to ${fmtDay(e.end_date)}` : fmtLong(e.event_date);
    return {
      html: `<div style="text-align:center">`
        + `<div style="font-family:${c.hf};font-size:21px;font-weight:800;color:#0B1220;line-height:1.25"><a href="${esc(link(c, e.url))}" target="_blank" style="color:#0B1220;text-decoration:none">${esc(p.title || e.title)}</a></div>`
        + `<div style="font-family:${c.bf};font-size:13px;color:#64748B;margin:4px 0 14px">${esc([range, e.venue].filter(Boolean).join(' · '))}</div></div>`
        + `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr>${box(days, days === 1 ? 'DAY TO GO' : 'DAYS TO GO')}${p.showGoing ? box(e.going ?? 0, 'GOING') : ''}${e.race_class ? box(esc(e.race_class), 'CLASS') : ''}</tr></table>`,
    };
  },
};

function addDays(s: string, n: number) {
  const v = ymd(s)!;
  const d = new Date(Date.UTC(v.y, v.m, v.d + n));
  return d.toISOString().slice(0, 10);
}

const mine = (e: FeedEvent, r: Reader) =>
  !e.class_key || !(r.boats && r.boats.length) || r.boats.some(b => (b.key || '').toLowerCase() === (e.class_key || '').toLowerCase());

function eventCard(c: Ctx, e: FeedEvent, p: BlockProps['events']) {
  const d = ymd(e.event_date);
  const r = c.o.reader;
  const status = r.answers?.[e.event_key];
  const base = r.token ? `${c.o.feed.club.appUrl}/whats-on/answer?t=${encodeURIComponent(r.token)}&e=${encodeURIComponent(e.event_key)}` : null;
  const badge = d ? `<table role="presentation" width="58" cellpadding="0" cellspacing="0" border="0" style="width:58px;border:1px solid #E3E8F0;border-radius:12px;border-collapse:separate;background:#F6F8FB"><tr><td align="center" style="padding:7px 0 6px;font-family:Arial,sans-serif;font-size:10px;font-weight:700;letter-spacing:0.08em;color:#64748B;line-height:1.3">${DAYS[d.dow].toUpperCase()}<br><span style="font-family:${c.hf};font-size:22px;font-weight:800;color:#0B1220;line-height:1.15">${d.d}</span><br>${MONTHS[d.m].toUpperCase()}</td></tr></table>` : '';
  const pill = (t: string, bg: string, fg: string) => `<span style="display:inline-block;margin:0 5px 5px 0;padding:3px 8px;border-radius:7px;background:${bg};color:${fg};font-family:Arial,sans-serif;font-size:10.5px;font-weight:700;letter-spacing:0.04em">${esc(t)}</span>`;
  const mineBoat = r.boats?.find(b => b.key && b.key === e.class_key && b.label);
  const labels = (e.race_class ? pill(e.race_class.toUpperCase(), '#F1F4F9', '#0B1220') : '')
    + (e.race_format ? pill(e.race_format.charAt(0).toUpperCase() + e.race_format.slice(1), '#F1F4F9', '#475569') : '')
    + (e.is_paid && e.entry_fee ? pill(`Entry ${money(e.entry_fee)}`, '#FFF4E5', '#8A5300') : '')
    + (mineBoat ? pill(`Your boat · ${mineBoat.label}`, '#EAF3FF', '#0A5CC2') : '');
  const meta = (t: string) => `<div style="font-family:${c.bf};font-size:13px;line-height:1.5;color:#475569">${t}</div>`;
  let h = (labels ? `<div style="line-height:22px;margin:0 0 3px">${labels}</div>` : '')
    + `<a href="${esc(link(c, e.url))}" target="_blank" style="font-family:${c.hf};font-size:17px;font-weight:800;line-height:1.3;color:#0B1220;text-decoration:none">${esc(e.title)}</a><div style="height:6px;line-height:6px;font-size:0">&nbsp;</div>`;
  if (p.showDetails) {
    if (e.end_date && e.end_date > e.event_date) h += meta(`${esc(fmtDay(e.event_date))} to ${esc(fmtDay(e.end_date))}`);
    if (e.venue) h += meta(esc(e.venue) + (e.map_url ? ` · <a href="${esc(link(c, e.map_url))}" target="_blank" style="color:${c.primary};font-weight:700;text-decoration:none">Map</a>` : ''));
    if (e.start_time) h += meta(`First start ${esc(e.start_time)}`);
  }
  if (p.showGoing) {
    const g = e.going || 0;
    h += meta(g === 0 ? 'Be the first to say you’re going' : `${g} going${status === 'yes' ? ' including you' : ''}`);
  }
  if (p.showAnswer) {
    if (status) {
      const map = { yes: ['#EAF8EF', '#136C34', '&#10003;&nbsp; <strong>You’re going</strong>'], no: ['#F1F4F9', '#475569', 'You said you can’t make it'], maybe: ['#FFF6E5', '#8A5300', 'You said maybe'] } as const;
      const m = map[status];
      h += `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin-top:10px;border-collapse:separate"><tr><td style="padding:9px 12px;border-radius:10px;background:${m[0]};color:${m[1]};font-family:${c.bf};font-size:13px">${m[2]}${base ? ` · <a href="${esc(link(c, base))}" target="_blank" style="color:inherit;font-weight:700">Change</a>` : ''}</td></tr></table>`;
    } else {
      const yes = base ? `${base}&a=yes` : e.url;
      const no = base ? `${base}&a=no` : e.url;
      h += `<div style="margin-top:12px"><table role="presentation" cellpadding="0" cellspacing="0" border="0"><tr><td style="padding-right:8px">${button(c, '✓  I’m going', yes, { small: true, style: 'solid' })}</td>`
        + (base ? `<td>${button(c, 'Can’t make it', no, { small: true, style: 'outline', color: '#64748B' })}</td>` : '')
        + '</tr></table></div>';
    }
  }
  return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="border:1px solid #E3E8F0;border-radius:${c.cardR}px;border-collapse:separate;background:#FFFFFF"><tr>`
    + `<td valign="top" width="58" style="width:58px;padding:16px 0 16px 16px">${badge}</td>`
    + `<td valign="top" style="padding:14px 16px 14px 14px">${h}</td></tr></table>`;
}

/* ── Whole email ───────────────────────────────────────────────────────────── */

export interface Rendered { html: string; head: string; body: string; text: string; blocks: number }

export function renderBlock(block: Block, o: RenderOptions, today = todayIn()): string {
  const c = ctxFor(o, block, today);
  const fn = R[block.type] as (c: Ctx, p: unknown) => Out;
  let out: Out = null;
  try {
    out = fn ? fn(c, block.props) : null;
  } catch (e) {
    out = o.edit ? { html: placeholder(`This block could not be shown (${(e as Error).message || 'error'})`) } : null;
  }
  if (!out || !out.html) return '';
  const mark = o.edit ? ` data-es-block="${esc(block.id)}" data-es-type="${block.type}"` : '';
  return out.bleed
    ? `<tr${mark}><td style="padding:0">${out.html}</td></tr>`
    : `<tr${mark}><td class="es-px" style="padding:14px 28px">${out.html}</td></tr>`;
}

function ctxFor(o: RenderOptions, block: Block, today: string): Ctx {
  const b = o.brand;
  return {
    o,
    brand: b,
    primary: hex(b.primary, '#2563EB'),
    dark: hex(b.dark, '#111827'),
    accent: hex(b.accent, '#F59E0B'),
    hf: stack(b.headingFont),
    bf: stack(b.bodyFont),
    btnR: b.corners === 'square' ? 0 : b.corners === 'round' ? 999 : 8,
    cardR: b.corners === 'square' ? 0 : b.corners === 'round' ? 16 : 10,
    today,
    block,
  };
}

export function emailHead(o: RenderOptions) {
  const fonts = Array.from(new Set([o.brand.headingFont, o.brand.bodyFont].filter(f => SAFE_FONTS.includes(f))));
  const fam = fonts.map(f => `family=${f.replace(/ /g, '+')}:wght@400;600;700;800`).join('&');
  return '<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="x-apple-disable-message-reformatting">'
    + `<title>${esc(o.subject || o.brand.clubName)}</title>`
    + (fam ? `<link href="https://fonts.googleapis.com/css2?${fam}&display=swap" rel="stylesheet">` : '')
    + '<style>body{margin:0;padding:0;-webkit-text-size-adjust:100%}table{border-collapse:collapse}img{-ms-interpolation-mode:bicubic}a{text-decoration:none}'
    + '@media only screen and (max-width:620px){.es-wrap{width:100%!important}.es-px{padding-left:18px!important;padding-right:18px!important}.es-col{display:block!important;width:100%!important;padding:0 0 14px 0!important}.es-outer{padding:0!important}.es-card{border-radius:0!important}}</style>';
}

export function emailBody(doc: EmailDoc, o: RenderOptions, today = todayIn()): { body: string; count: number } {
  const rows = doc.blocks.map(b => renderBlock(b, o, today)).filter(Boolean);
  const bf = stack(o.brand.bodyFont);
  const pre = o.previewText
    ? `<div style="display:none;max-height:0;overflow:hidden;mso-hide:all;font-size:1px;line-height:1px;color:#F3F5F8">${esc(fillTokens(o.previewText, o.reader, o.brand))}${'&nbsp;&zwnj;'.repeat(60)}</div>`
    : '';
  const lnk = (u: string | null | undefined, t: string) => `<a href="${esc(o.edit ? '#' : (u || '#'))}" target="_blank" style="color:#64748B;text-decoration:underline">${t}</a>`;
  const footer = `<table role="presentation" class="es-wrap" width="600" cellpadding="0" cellspacing="0" border="0" style="width:600px;max-width:600px"><tr><td class="es-px" align="center" style="padding:22px 28px 8px;font-family:${bf};font-size:12px;line-height:1.6;color:#64748B">`
    + `<strong style="color:#334155">${esc(o.brand.clubName)}</strong>${o.footerAddress ? ` · ${esc(o.footerAddress)}` : ''}<br>`
    + (o.reader.is_member ? `You’re getting this because you’re a member of ${esc(o.brand.clubName)}.` : `You’re getting this because you’ve sailed with or signed up to hear from ${esc(o.brand.clubName)}.`)
    + `<br>${lnk(o.preferencesUrl, 'Email preferences')} &nbsp;·&nbsp; ${lnk(o.unsubscribeUrl, 'Unsubscribe')}${o.viewInBrowserUrl ? ` &nbsp;·&nbsp; ${lnk(o.viewInBrowserUrl, 'View in browser')}` : ''}`
    + `<div style="margin-top:10px;font-size:11px;color:#94A3B8">Sent with AlfiePRO</div></td></tr></table>`;
  const body = pre
    + `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="#F3F5F8" style="background:#F3F5F8"><tr><td class="es-outer" align="center" style="padding:24px 12px">`
    + `<table role="presentation" class="es-wrap es-card" width="600" cellpadding="0" cellspacing="0" border="0" bgcolor="#FFFFFF" style="width:600px;max-width:600px;background:#FFFFFF;border-radius:14px;overflow:hidden;border-collapse:separate">`
    + (rows.length ? rows.join('') : `<tr><td style="padding:40px 28px">${o.edit ? placeholder('Add blocks from the left to start your email') : ''}</td></tr>`)
    + '<tr><td style="height:14px;line-height:14px;font-size:0">&nbsp;</td></tr></table>'
    + footer
    + '</td></tr></table>'
    + (o.openPixel && !o.edit ? `<img src="${esc(o.openPixel)}" width="1" height="1" alt="" style="display:block;width:1px;height:1px;border:0">` : '');
  return { body, count: rows.length };
}

export function renderEmail(doc: EmailDoc, o: RenderOptions, today = todayIn()): Rendered {
  const head = emailHead(o);
  const { body, count } = emailBody(doc, o, today);
  const html = `<!DOCTYPE html><html lang="en"><head>${head}</head><body style="margin:0;padding:0;background:#F3F5F8">${body}</body></html>`;
  return { html, head, body, text: htmlToText(body), blocks: count };
}

/** Plain-text version for the text/plain part. */
export function htmlToText(html: string) {
  return html
    .replace(/<div style="display:none[^]*?<\/div>/, '')
    .replace(/<a [^>]*href="([^"#][^"]*)"[^>]*>([^<]*)<\/a>/g, (_m, u, t) => (t && t.trim() ? `${t.trim()} (${u.replace(/&amp;/g, '&')})` : ''))
    .replace(/<\/td>/gi, ' ')
    .replace(/<(br|\/p|\/div|\/tr|\/li|\/h\d)[^>]*>/gi, '\n')
    .replace(/<li[^>]*>/gi, '• ')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;|&zwnj;/g, ' ')
    .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&#10003;/g, '✓').replace(/&#9654;/g, '▶')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n\s*\n\s*\n+/g, '\n\n')
    .trim();
}

/** Every link in a doc that isn't filled in yet, or doesn't look like a web address. */
export function linkProblems(doc: EmailDoc): { blockId: string; what: string }[] {
  const out: { blockId: string; what: string }[] = [];
  const bad = (u?: string | null) => !!u && !okUrl(u);
  for (const b of doc.blocks) {
    const p = b.props as any;
    if (b.type === 'button' && p.text && !okUrl(p.url)) out.push({ blockId: b.id, what: `Button “${p.text}” has no link` });
    if (b.type === 'hero' && p.buttonText && !okUrl(p.url)) out.push({ blockId: b.id, what: `Hero button “${p.buttonText}” has no link` });
    if (b.type === 'image' && bad(p.url)) out.push({ blockId: b.id, what: 'An image link is not a web address' });
    if (b.type === 'columns') (p.items || []).forEach((it: any) => { if (it.buttonText && !okUrl(it.url)) out.push({ blockId: b.id, what: `Card button “${it.buttonText}” has no link` }); });
    if (b.type === 'text') for (const m of String(p.text || '').matchAll(/\[([^\]]+)\]\(([^)\s]*)\)/g)) if (!okUrl(m[2])) out.push({ blockId: b.id, what: `Link “${m[1]}” is not a web address` });
  }
  return out;
}

/** Images without a description (alt text). */
export const missingAlt = (doc: EmailDoc) => doc.blocks.filter(b => b.type === 'image' && okUrl((b.props as any).src) && !String((b.props as any).alt || '').trim()).map(b => b.id);

